import {calendarHTML} from './ski-calendar.js';
const colors={Friday:'#387ac5',Saturday:'#e96928',Sunday:'#167c78'};
export function tripLegs(t){
 if(!t.days)return [];
 if(t.hotel)return [{day:'Friday',from:0,to:t.hotel},{day:'Saturday',from:t.hotel,to:t.sat},{day:'Saturday',from:t.sat,to:t.hotel},{day:'Sunday',from:t.hotel,to:t.sun},{day:'Sunday',from:t.sun,to:0}];
 return [...(t.sat?[{day:'Saturday',from:0,to:t.sat},{day:'Saturday',from:t.sat,to:0}]:[]),...(t.sun?[{day:'Sunday',from:0,to:t.sun},{day:'Sunday',from:t.sun,to:0}]:[])];
}
export function createRouteMap(data,routing){
 const $=id=>document.getElementById(id),points=new Map([data.home,...data.mountains,...data.hotels].map(p=>[p.id,p]));
 let map,selected=[],settings={},active={},generation=0,stale=false,layers;
 function renderCalendar(){if(stale){$('ski-calendar').innerHTML='<p class="note">Inputs changed. Optimize again to refresh the calendar.</p>';return;}$('ski-calendar').innerHTML=calendarHTML(data,selected,settings,active,$('map-week').value);$('ski-calendar').querySelectorAll('[data-calendar-week]').forEach(el=>el.onclick=()=>{$('map-week').value=el.dataset.calendarWeek;show();});}
 const roadCache=new Map(),requests=new Map();
 const cached=fetch('road-routes.json').then(r=>r.ok?r.json():{}).then(d=>{for(const [k,v]of Object.entries(d))roadCache.set(k,v)}).catch(()=>{});
 function init(){if(map)return;map=L.map('route-map',{scrollWheelZoom:false}).setView([43.45,-72.4],7);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);layers=L.layerGroup().addTo(map);}
 async function road(a,b){const key=a+'_'+b;await cached;if(roadCache.has(key))return roadCache.get(key);if(requests.has(key))return requests.get(key);const p=points.get(a),q=points.get(b),url=`https://router.project-osrm.org/route/v1/driving/${p.lon},${p.lat};${q.lon},${q.lat}?overview=full&geometries=geojson&steps=false`;const promise=fetch(url).then(r=>{if(!r.ok)throw Error('Road routing unavailable');return r.json()}).then(r=>{if(r.code!=='Ok')throw Error('No road route');let line=r.routes[0].geometry.coordinates;roadCache.set(key,line);return line;}).finally(()=>requests.delete(key));requests.set(key,promise);return promise;}
 async function show(){
  init();map.invalidateSize();layers.clearLayers();renderCalendar();const run=++generation;
  if(stale){$('map-status').textContent='Inputs changed. Optimize again to refresh the route map.';$('map-legs').innerHTML='';return;}
  const week=$('map-week').value,ts=selected.filter(t=>t.days&&(week==='all'||t.w===week)),visible=new Set([...document.querySelectorAll('[data-map-day]:checked')].map(x=>x.dataset.mapDay)),legs=ts.flatMap(t=>tripLegs(t).filter(l=>visible.has(l.day)).map(l=>({...l,w:t.w}))),unique=new Map();for(const l of legs)unique.set(`${l.day}_${l.from}_${l.to}`,l);
  const stops=new Set(legs.flatMap(l=>[l.from,l.to])),bounds=[];
  for(const id of stops){const p=points.get(id),hotel=data.hotels.some(h=>h.id===id),mountain=data.mountains.some(m=>m.id===id),pos=[p.lat,p.lon];bounds.push(pos);L.circleMarker(pos,{radius:id===0?8:hotel?6:7,color:'#fff',weight:2,fillColor:id===0?'#102b3a':hotel?'#8b5aac':'#e96928',fillOpacity:1}).bindTooltip(p.name,{permanent:true,direction:'right',className:'map-stop-label',opacity:1}).bindPopup(`<b>${p.name}</b><br>${id===0?'Home':mountain?'Mountain':'Lodging town center'}`).addTo(layers);}
  if(bounds.length)map.fitBounds(bounds,{padding:[35,35],maxZoom:11});$('map-status').textContent=legs.length?'Drawing road routes…':'No ski trips or days selected.';
  $('map-legs').innerHTML=ts.map(t=>{const p=data.mountains.find(m=>m.id===t.sat),q=data.mountains.find(m=>m.id===t.sun);const all=tripLegs(t),stops=[all[0].from,...all.map(l=>l.to)],coord=id=>{let p=points.get(id);return p.lat+','+p.lon},directions='https://www.google.com/maps/dir/?api=1&travelmode=driving&origin='+coord(stops[0])+'&destination='+coord(stops.at(-1))+'&waypoints='+encodeURIComponent(stops.slice(1,-1).map(coord).join('|'));return `<details ${week!=='all'?'open':''}><summary>${t.w} · ${p?.name||'Off'} / ${q?.name||'Off'}${p?.name==='Magic'&&q?.name==='Magic'?' · REQUIRED MAGIC WEEKEND':''}</summary><div class="table-wrap"><table class="legs-table"><thead><tr><th>Day</th><th>Road leg</th><th>Adjusted time</th><th>Distance</th></tr></thead><tbody>${all.map(l=>`<tr><td style="color:${colors[l.day]}">${l.day}</td><td>${points.get(l.from).name} → ${points.get(l.to).name}</td><td>${(routing.durations[l.from][l.to]/3600*(1+settings.traffic/100)).toFixed(2)} h</td><td>${Math.round(routing.distances[l.from][l.to]/1609.344)} mi</td></tr>`).join('')}</tbody></table></div><p><a href="${directions}" target="_blank" rel="noopener">Open this itinerary in Google Maps</a></p></details>`;}).join('');
  let failed=0;for(const l of unique.values()){try{const line=await road(l.from,l.to);if(run!==generation)return;const latlng=line.map(([lon,lat])=>[lat,lon]);bounds.push(...latlng);L.polyline(latlng,{color:colors[l.day],weight:l.day==='Friday'?6:4,opacity:.72,dashArray:l.day==='Friday'?'8 5':null}).bindPopup(`<b>${l.day}</b><br>${points.get(l.from).name} → ${points.get(l.to).name}`).addTo(layers);}catch{failed++;}}
  if(run===generation&&bounds.length)map.fitBounds(bounds,{padding:[35,35],maxZoom:11});if(run===generation)$('map-status').textContent=failed?`${failed} road legs could not load. Stops and itinerary links remain available.`:`${ts.length} weekend${ts.length===1?'':'s'} · ${unique.size} distinct road legs · click a line or stop for details.`;
 }
 let labelsVisible=false;$('route-map').classList.add('hide-stop-labels');$('map-labels').onclick=()=>{labelsVisible=!labelsVisible;$('route-map').classList.toggle('hide-stop-labels',!labelsVisible);$('map-labels').textContent=labelsVisible?'Hide labels':'Show labels';$('map-labels').setAttribute('aria-pressed',String(labelsVisible));};
 $('map-week').onchange=show;document.querySelectorAll('[data-map-day]').forEach(el=>el.onchange=show);
 return {show,update(trips,s,a={}){selected=trips;settings=s;active=a;stale=false;const old=$('map-week').value;$('map-week').innerHTML='<option value="all">Whole season</option>'+trips.filter(t=>t.days).map(t=>`<option value="${t.w}">${t.w}${t.sat===5&&t.sun===5?' · Magic weekend':''}</option>`).join('');if([...$('map-week').options].some(o=>o.value===old))$('map-week').value=old;renderCalendar();},invalidate(){stale=true;generation++;renderCalendar();if(map){layers.clearLayers();$('map-status').textContent='Inputs changed. Optimize again to refresh the route map.';$('map-legs').innerHTML='';}}};
}
